-- Foto da Pomada em Pó Mirras 10g (fundo removido)
INSERT INTO "stored_files" ("id","area","fileName","mimeType","sizeBytes","data","createdAt")
SELECT gen_random_uuid(),'products','della-pom-003-mi108.webp','image/webp',39950,decode('','hex'),now() WHERE NOT EXISTS (SELECT 1 FROM "stored_files" WHERE "fileName"='della-pom-003-mi108.webp');
INSERT INTO "product_images" ("id","productId","fileName","mimeType","isPrimary","sortOrder","createdAt")
SELECT gen_random_uuid(),p."id",'della-pom-003-mi108.webp','image/webp',true,0,now() FROM "products" p
 WHERE p."sku"='POM-003-MI108' AND NOT EXISTS (SELECT 1 FROM "product_images" i WHERE i."productId"=p."id");
